          ignitionAndEngine: [ 
            { interval: "Immediately", timeLimit: "Unlimited", task: "Charge Pipe Upgrade", details: "CRITICAL: Replace the brittle plastic factory charge pipe with an aluminum unit. The MPPK boost makes explosion inevitable.", parts: ["VRSF / FTP Aluminum Pipe"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" },
            { interval: "50,000 km", timeLimit: "5 years", task: "Spark Plug Replacement", details: "CRITICAL: Direct-injected turbo engines eat spark plugs. Replace to prevent misfires under load.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "240 EUR" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Valve Cover Replacement", details: "CRITICAL: The integrated PCV membrane fails, causing a loud whistle, vacuum leak, and oil weeping onto the exhaust. Replace the entire cover.", parts: ["Valve Cover Assembly"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "500 EUR" },
            { interval: "60,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber gasket before it leaks oil onto the belt. MUST PERFORM ELECTRONIC OIL PRIME AFTER REPLACEMENT.", parts: ["Elring OFHG Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "400 EUR" }
          ],
          preventiveAndSuspension: [ 
            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace the primary drive belt immediately if any oil has leaked onto it from the OFHG.", parts: ["Continental Belt Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "120 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Control Arm Bushings", details: "Replace front thrust arm bushings. The heavy 3.0L inline-6 places massive stress on the front end.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" }
          ],
