        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The B47D20A is part of BMW's highly successful modular family. The closed-deck design provides extreme rigidity, optimized for ultra-low NVH and strict Euro 6 emissions targets.", crankshaft: "Forged Steel, supported by 5 main bearings, featuring integrated twin balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "16-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Extreme Software Detune (Fleet Edition). This 136hp model is the ultimate sleeper. Mechanically completely identical to the 190hp model, it is severely artificially choked via software to meet extreme corporate tax brackets (often in Belgium). It retains 360Nm of torque, making it feel adequate in the city, but hides massive tuning potential for the highway." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,000 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (The updated ZF 8HP transmission handles this perfectly).", maxSafePowerStock: "240 hp (The B47 block easily handles this power level).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable)." } },
