        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The B47D20B is part of BMW's highly successful modular family. The closed-deck design provides extreme rigidity, optimized for ultra-low NVH and strict Euro 6d-TEMP emissions targets.", crankshaft: "Forged Steel, supported by 5 main bearings, featuring integrated twin balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "16-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "TU1 Upgrade: Sequential Twin-Turbos. The transition to the TU1 engine brought a massive upgrade: a sequential twin-turbocharger setup (one small high-pressure, one large low-pressure). This setup completely eliminates diesel lag and provides a massive flat torque curve, making the 2.0L diesel feel incredibly responsive and much larger than its displacement suggests." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail). High pressure system for Euro 6d-TEMP compliance.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (The updated ZF 8HP transmission handles this perfectly).", maxSafePowerStock: "260 hp (The B47 Twin-Turbo block easily handles this power level).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), Vacuum Hoses (Turbo Lag), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, vacuum, and cooling failures inherent to the modern B47 Twin-Turbo diesel.", parts: [ { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "CRITICAL: Replaces brittle lines to cure turbo lag and limp mode." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6d exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." } ] },
