        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The N47 marked BMW's transition to all-aluminum diesel blocks. While the block itself is rigid, the engine is deeply flawed by its rear-mounted timing chain and fragile fuel system.", crankshaft: "Forged Steel, supported by 5 main bearings, featuring integrated twin balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "16-valve DOHC design. The intake tracts are prone to extremely rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by the notoriously fragile rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Rear Timing Chain Design. BMW relocated the timing chain to the rear of the engine (transmission side) to improve pedestrian safety regulations and NVH. Unfortunately, this makes servicing the chain incredibly expensive and labor-intensive, as the engine or transmission must be removed." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "1,800 Bar (Fuel Rail). Uses the notoriously fragile Bosch CP4 pump.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (The ZF 8HP45 transmission handles this perfectly).", maxSafePowerStock: "230 hp (The N47 block handles this, but high EGTs risk DPF melting).", maxSafeRPM: "4800 RPM", weakestLink: "Timing Chain (Snaps), CP4 Fuel Pump (Disintegrates), EGR Cooler (Fire Risk), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE7 (Highly tunable)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic timing chain, CP4, and EGR failures inherent to the N47 diesel.", parts: [ { category: "Timing Chain Kit", brand: "Genuine BMW / Febi", note: "CRITICAL: Replace entirely before 150k km." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "CRITICAL: Replace every 20k km to protect the fragile CP4 pump." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "Water Pump", brand: "Saleri", note: "Replace proactively to prevent cooling loss." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace alongside the vibration damper." } ] },
