            { interval: "Immediately", timeLimit: "Unlimited", task: "EGR Cooler Recall Check", details: "CRITICAL: Verify that the revised EGR cooler is installed to prevent engine fires.", parts: ["BorgWarner Cooler"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "0 EUR (Recall)" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Clear the thick carbon sludge from the intake ports caused by the massive EGR flow.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "400 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay Replacement", details: "Replace all 6 glow plugs and the module. Essential for triggering DPF regens.", parts: ["6x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "220 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "Proactively replace the main crankshaft pulley before it shears off and destroys the belt.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }
