          { partName: "NOx Sensor (Front)", category: "Exhaust", oem: { brand: "BMW Genuine", code: "13628589846", approxPrice: "550 EUR" }, crossRef: { brand: "Bosch", code: "0281006591", approxPrice: "350 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=13628589846", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=13628589846" }, note: "Common failure point in SCR system." }
