            { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "280 EUR" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Valve Cover Replacement", details: "CRITICAL: The integrated PCV membrane fails, causing a loud whistle and vacuum leak. Replace the entire cover.", parts: ["Valve Cover Assembly"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "550 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "450 EUR" }
