        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B48TU2 is part of BMW's highly successful modular engine family. The closed-deck design provides extreme rigidity.", crankshaft: "Forged Steel, supported by 5 main bearings, featuring integrated twin balance shafts.", pistonSpeed: "16.8 m/s @ 6500 RPM.", alternator: "48V Integrated Starter Generator (ISG).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a high 11.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Miller Cycle combustion design.", intakePortFlow: "16-valve DOHC design. Integrates Valvetronic and Double-VANOS.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides.", lifterType: "Hydraulic bucket tappets.", specialFeature: "TU2 Architecture (Integrated Manifold & Dual Injection). A massive upgrade. The exhaust manifold is now cast directly into the cylinder head and liquid-cooled, rapidly reducing EGTs. Furthermore, it utilizes Dual Injection (Port + Direct), virtually eliminating the carbon buildup that plagued all previous direct-injected engines. The 184hp output is an artificial software restriction." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the Thermal Management Module.", oilCooler: "Integrated heat exchanger." }, fuelSystem: { systemType: "Dual Injection (350 Bar Direct + Low Pressure Port Injection).", maxPressure: "350 Bar (Fuel Rail).", injectors: "4x High-Pressure Direct + 4x Low-Pressure Port Injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (The updated ZF 8HP transmission handles this perfectly).", maxSafePowerStock: "350+ hp (The closed-deck B48 block handles massive power safely).", maxSafeRPM: "7000 RPM", weakestLink: "Plastic Coolant Lines (Snap), Thermal Management Module (Fails internally), ECU Encryption." }, electrical: { coils: "Individual Coil Pack system.", ecu: "Bosch MG1CS201 (Heavily encrypted, requires FEMTO bench unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the cooling and electrical failures inherent to the modern B48 MHEV petrol engine.", parts: [ { category: "Thermal Management Module", brand: "Genuine BMW", note: "CRITICAL: Replace if engine runs too cold or overheats." }, { category: "Coolant Vent Line", brand: "VRSF / Genuine BMW", note: "CRITICAL: Proactively replace the brittle plastic line." }, { category: "Valve Cover Assembly", brand: "Genuine BMW / Elring", note: "Required when the integrated PCV membrane tears." }, { category: "Oil Filter Housing Base", brand: "Genuine BMW", note: "Replace if oil and coolant begin mixing." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Replace every 50k km to prevent under-load misfires." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Replace proactively to ensure perfect spark." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Replaces the weak factory plastic unit." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to ensure accessory reliability." } ] },
