  engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B58 is a monumental engineering feat. The closed-deck design provides extreme rigidity, optimized to handle insane cylinder pressures.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, resulting in a buttery-smooth, refined inline-6 experience.", pistonSpeed: "16.1 m/s @ 6500 RPM.", alternator: "48V Integrated Starter Generator (ISG).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features an 11.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "24-valve DOHC design. Integrates Valvetronic and Double-VANOS.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides.", lifterType: "Hydraulic bucket tappets.", specialFeature: "B58 Technical Update 1 (TU1) & 48V MHEV. The EU LCI model utilizes the heavily revised TU1 engine, featuring an integrated exhaust manifold, a one-piece timing chain, and the 350-bar HPFP. It also introduces a 48V electric motor to assist the engine off the line. However, it is severely restricted by European OPF emissions regulations, muting the sound compared to US models." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the Heat Management Module.", oilCooler: "Integrated heat exchanger." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail). The TU1 HPFP provides massive fueling headroom.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (The ZF 8HP51 handles this perfectly).", maxSafePowerStock: "600 hp (The closed-deck B58TU1 block handles massive power safely. The factory HPFP easily supports E30 blends).", maxSafeRPM: "7000 RPM", weakestLink: "Heat Management Module (Fails internally), Plastic Charge Pipe (Explodes), OPF Filters (Choke exhaust flow), ECU Encryption." }, electrical: { coils: "Individual Coil Pack system.", ecu: "Bosch MG1 (Heavily encrypted, mandates FEMTO bench unlock)." } },
  recommendedParts: { description: "Crucial maintenance parts to prevent the cooling and vacuum failures inherent to the B58 petrol engine.", parts: [ { category: "Heat Management Module", brand: "Genuine BMW", note: "CRITICAL: Replace if engine runs too cold or overheats." }, { category: "Valve Cover Assembly", brand: "Genuine BMW / Elring", note: "Required when the integrated PCV membrane tears." }, { category: "Oil Filter Housing Base", brand: "Genuine BMW", note: "Replace if oil and coolant begin mixing." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Replace every 40k km to prevent under-load misfires." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Replace proactively to ensure perfect spark." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Replaces the weak factory plastic unit." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to ensure accessory reliability." }, { category: "48V AGM Battery", brand: "Genuine BMW", note: "Essential for MHEV stability." } ] },
