  engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The B57 is a legendary engine, providing extreme rigidity and perfect natural balance. The closed-deck design handles massive boost and compression effortlessly, making it the king of modern diesels.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts and resulting in a buttery-smooth, refined inline-6 diesel experience.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "180A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "24-valve DOHC design. The intake tracts are prone to extremely rapid carbon clogging from the massive EGR flow.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a highly reliable rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Extreme Software Detune (Fleet Edition). This 211hp model is the ultimate sleeper. Mechanically identical to the 265hp model, it is artificially choked via software to meet extreme corporate tax brackets (often in Belgium). It retains the full 620Nm of torque, making it feel identical in the city, but hides massive tuning potential for the highway." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail). Uses a highly reliable upgraded fuel pump compared to the old CP4.", injectors: "6x Bosch Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The heavy-duty ZF 8HP75 transmission handles this perfectly).", maxSafePowerStock: "380 hp (The B57 block handles this, but high EGTs risk DPF melting).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable via OBD)." } },
  recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, and cooling failures inherent to the modern B57 diesel.", parts: [ { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6 exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Water Pump", brand: "Saleri", note: "Replace proactively to prevent cooling loss." } ] },
