  engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The B57 is a legendary engine, providing extreme rigidity and perfect natural balance. The closed-deck design handles massive boost and compression effortlessly, making it the king of modern diesels.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts and resulting in a buttery-smooth, refined inline-6 diesel experience.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "48V Integrated Starter Generator (ISG).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "24-valve DOHC design. The intake tracts are prone to extremely rapid carbon clogging from the massive EGR flow.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a highly reliable rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "M-Performance LCI Upgrade. The T2 engine is a massive leap forward. It utilizes a sequential twin-turbocharger setup completely eliminating diesel lag. Furthermore, it integrates a 48V electric motor to assist the engine off the line, boosting power to 340hp and a brutal 700Nm of torque." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,700 Bar (Fuel Rail). Ultra-high pressure system for Euro 6d compliance.", injectors: "6x Bosch Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "850 Nm (The updated ZF 8HP75 transmission handles this perfectly).", maxSafePowerStock: "450 hp (The B57 Twin-Turbo block easily handles this power level).", maxSafeRPM: "4800 RPM", weakestLink: "Vacuum Hoses (Turbo Lag), EGR Cooler (Fire Risk), SCR System (NOx Sensors), ECU Encryption." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Heavily encrypted, mandates FEMTO bench unlock)." } },
  recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, vacuum, and cooling failures inherent to the modern B57 Twin-Turbo diesel.", parts: [ { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "CRITICAL: Replaces brittle lines to cure turbo lag and limp mode." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6d exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2700-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "48V AGM Battery", brand: "Genuine BMW", note: "Essential for MHEV stability." } ] },
